'use strict';
const Dashboard={filters:{},snapshot:null,async init(){if(!Business.can('dashboard:read'))return;const nav=document.createElement('a');nav.href='#dashboard';nav.dataset.legacyMain='overview';nav.innerHTML='<span>◫</span> 信息总览';nav.setAttribute('aria-label','信息总览');document.querySelector('.sidebar nav').prepend(nav);const section=document.createElement('section');section.id='dashboard';section.className='dashboard';section.innerHTML='<div class="page-heading"><div><div class="eyebrow">PRODUCT WMS · MUSONOI PROJECT</div><h1>信息总览</h1><a class="button secondary" href="#inventory">进入库存查询 ↓</a><p>厂内实物、有效锁定与正式离场，统一按数据库记账版本统计。</p></div></div><details class="panel overview-filter-box"><summary>统计范围与截止日期（展开筛选）</summary><div id="dashboard-filters"></div></details><p id="dashboard-error" class="error" role="alert"></p><div id="dashboard-content"></div>';document.querySelector('#inventory').before(section);const back=document.createElement('a');back.href='#dashboard';back.className='button secondary';back.textContent='返回信息总览 ↑';document.querySelector('#inventory .page-heading').append(back);const m=await Business.load(),today=new Intl.DateTimeFormat('en-CA',{timeZone:'Africa/Lubumbashi',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date()),select=(label,key,rows,name)=>`<label>${label}<select name="${key}">${Business.options(rows,null,name,true)}</select></label>`;$('dashboard-filters').innerHTML=`<form id="dashboard-form" class="panel filters"><div class="form-grid">${Flow.field('统计截止日期','to','date',today,'required')}${select('货权客户','customer_id',m.customers,'name')}${select('仓库','warehouse_id',m.warehouses,'name')}${select('堆场','yard_id',m.yards,'name')}${select('货位','location_id',m.locations,'code')}${select('生产批次','batch_id',m.batches,'code')}</div><button class="button primary">刷新信息总览</button></form>`;$('dashboard-form').onsubmit=async e=>{e.preventDefault();this.filters=Object.fromEntries(new FormData(e.target));e.submitter.disabled=true;try{await this.refresh();}finally{e.submitter.disabled=false;}};this.filters={to:today};await this.refresh();let timer;window.addEventListener('inventory-changed',()=>{clearTimeout(timer);timer=setTimeout(()=>this.refresh(),300);});window.addEventListener('session-expired',()=>{$('dashboard-content').replaceChildren();});},bars(title,rows,key='physical_weight'){const max=Math.max(1,...rows.map(x=>Number(x[key])));return `<section class="panel dashboard-chart"><h3>${title}（吨）</h3>${rows.length?rows.map(x=>`<div class="dashboard-bar-row"><span>${esc(x.dimension)}</span><meter min="0" max="${max}" value="${Number(x[key])}" aria-label="${esc(x.dimension)}"></meter><strong>${esc(Tonnes.format(x[key]))}</strong></div>`).join(''):'<p>当前授权范围无记录</p>'}</section>`;},async refresh(){try{const q=new URLSearchParams(Object.entries(this.filters).filter(([,v])=>v)),r=await API.request('/dashboard?'+q);this.snapshot=r;$('dashboard-error').textContent='';$('dashboard-content').innerHTML=`<p class="dialog-notice">${esc(r.notice)}<br>截止${esc(r.window.end)} · 库存版本${esc(r.window.end_revision)} · 单位：吨。${esc(r.warning_notice)}</p>${r.workflow_metrics?'<h2>捆包业务状态</h2><p>正式账面包含已离场待审批货物；现场实物已排除它们。未检斤重量不参与汇总。</p><div class="dashboard-metrics">'+Object.entries({total_bundles:'库存总捆数',total_sheets:'库存已知总片数',missing_sheets_count:'片数未录入捆数',working_bundles:'备货作业中捆数',pending_lots:'待备货审核Lot数',sampling_bundles:'正在取样捆数',unweighed_bundles:'待检斤捆数',weighed_bundles:'已检斤捆数',available_bundles:'可备货捆数',locked_bundles:'已锁定捆数',prepared_bundles:'已备货待装车',loaded_bundles:'已装车待离场',departed_pending_bundles:'已离场待审批/纠正',outbound_bundles:'已正式出库',onsite_bundles:'现场实物捆数',onsite_known_weight:'现场已知净重(t)',ledger_known_weight:'正式账面已知净重(t)'}).map(([k,label])=>'<article class="panel dashboard-card"><span>'+label+'</span><strong>'+esc(k.endsWith('_weight')?Tonnes.format(r.workflow_metrics[k]):r.workflow_metrics[k]??'未录入')+'</strong></article>').join('')+'</div>':''}<h2>正式库存账与历史统计</h2><div class="dashboard-metrics">${Object.entries(r.metric_labels).map(([k,label])=>`<button class="panel dashboard-card" data-dashboard-metric="${k}"><span>${esc(label)}</span><strong class="${String(r.metrics[k]).length>10?'compact-number':''}">${esc(k==='exceptions'?r.metrics[k]:format(r.metrics[k]))}<small>${k==='exceptions'?'项':'吨'}</small></strong><span>查看授权明细 →</span></button>`).join('')}</div><div class="dashboard-grid"><section class="panel dashboard-chart"><h3>本月库存趋势（吨）</h3>${this.bars('每日收盘实物',r.trend.map(x=>({dimension:x.period,physical_weight:x.closing_weight})))}${Control.reportTable(r.trend.map(x=>({period:x.period,opening_weight:x.opening_weight,inbound_weight:x.inbound_weight,outbound_weight:x.outbound_weight,closing_weight:x.closing_weight})))}</section>${this.bars('库存库龄',r.age)}${this.bars('客户分配',r.allocations)}${this.bars('货位分布',r.locations)}</div><p>期初${esc(Tonnes.format(r.summary.opening_weight))} + 本期流转${esc(Tonnes.format(r.summary.movement_net))} = 期末${esc(Tonnes.format(r.summary.closing_weight))}；勾稽差额${esc(Tonnes.format(r.summary.reconciliation_difference))}吨。盘亏调整不计入正式离场出库。</p>`;document.querySelectorAll('[data-dashboard-metric]').forEach(b=>b.onclick=()=>this.details(b.dataset.dashboardMetric).catch(e=>notify(e.message)));}catch(e){$('dashboard-error').textContent=e.message;$('dashboard-content').replaceChildren();this.snapshot=null;}},async details(metric){if(!this.snapshot)throw Error('请先刷新信息总览');const q=new URLSearchParams({...this.filters,metric,as_of:this.snapshot.window.end}),r=await API.request('/dashboard/details?'+q);Business.open(r.title+' · 截止版本明细',`<p>截止${esc(r.window.end)} · 库存版本${esc(r.window.end_revision)}；服务端按当前账号数据范围过滤。</p>${Control.reportTable(r.rows)}`);}};
Object.assign(Control.reportLabels,{location:'货位',batch:'生产批次',customer:'货权客户',allocated_customer:'分配客户',vehicle_no:'车辆',inbound_at:'入库时间'});
Dashboard.ready=Dashboard.init().catch(e=>notify(e.message));
